'use strict';
// Visual randomness has its own generator so effects cannot change CPU decisions.
let detailSeed=27183,detailClock=0,detailSparks=[],detailBursts=[],detailGhosts=[],detailTrailClock=0;
const detailFeet=new WeakMap();
const EFFECT_PALETTES={volt:['#bdf7ff','#55bdff','#fff9d0'],ember:['#ffdfa0','#ff8b35','#dc4332'],cipher:['#e3c9ff','#ab8bff','#7fe8e5'],brick:['#f4d6a2','#c18d64','#8d7058'],jade:['#d9ffcb','#75e6bb','#f1ffe4'],rook:['#d5efff','#8bb3d2','#d5c3a1'],haze:['#ffd4f4','#e878cf','#b6ecff'],goldie:['#fff2b1','#edbc4b','#ffdf72']};
function detailRandom(){detailSeed=(Math.imul(detailSeed,1664525)+1013904223)>>>0;return detailSeed/4294967296}
function detailSpark(x,y,color,vx,vy,life=.3,kind='spark'){const cap=strongEffects?180:28;if(detailSparks.length>=cap)detailSparks.shift();detailSparks.push({x,y,color,vx,vy,life,max:life,kind})}
function detailBurst(x,y,id,blocked,heavy,superHit=false){const palette=EFFECT_PALETTES[id]||EFFECT_PALETTES.volt,color=blocked?'#a6eaff':palette[0];detailBursts.push({x,y,id,color,blocked,heavy,superHit,age:0,life:blocked?.3:heavy?.5:.3,seed:detailRandom()*20});if(detailBursts.length>20)detailBursts.shift();
 const count=strongEffects?(superHit?24:heavy?18:10):4;
 for(let i=0;i<count;i++){const angle=detailRandom()*Math.PI*2,speed=(heavy?100:65)+detailRandom()*(superHit?280:160);detailSpark(x,y,blocked?'#b7eaff':palette[i%3],Math.cos(angle)*speed,Math.sin(angle)*speed,.15+detailRandom()*.32,blocked?'guard':id==='ember'?'ember':'spark')}
 if(heavy&&!blocked)for(let i=0;i<(strongEffects?10:2);i++)detailSpark(x,ground-2,palette[2],(detailRandom()-.5)*260,-30-detailRandom()*110,.35+detailRandom()*.2,'dust');
}
const hitBeforeDetail=applyCombatHit;applyCombatHit=function(a,t,m,d){const hp=t.hp,ok=hitBeforeDetail(a,t,m,d);if(ok&&t.hp<hp){const blocked=t.blockstun>0;detailBurst(t.x-d*15,t.y-(m.height==='low'?30:85),a.character,blocked,m.damage>=12||m.grab||m.knockdown,!!m.isSuper)}return ok};
const resetBeforeDetail=resetRound;resetRound=function(){detailSparks=[];detailBursts=[];detailGhosts=[];detailTrailClock=0;resetBeforeDetail()};
function updateDetailEffects(dt){detailClock+=dt;detailTrailClock+=dt;
 for(const s of detailSparks){s.life-=dt;s.x+=s.vx*dt;s.y+=s.vy*dt;s.vx*=Math.max(0,1-dt*2);s.vy+=(s.kind==='dust'?220:s.kind==='ember'?-80:420)*dt}
 detailSparks=detailSparks.filter(s=>s.life>0).slice(-(strongEffects?180:28));for(const b of detailBursts)b.age+=dt;detailBursts=detailBursts.filter(b=>b.age<b.life);for(const g of detailGhosts)g.life-=dt;detailGhosts=strongEffects?detailGhosts.filter(g=>g.life>0).slice(-6):[];
 for(const f of [player,enemy]){let feet=detailFeet.get(f);if(!feet){feet={y:f.y,dust:0};detailFeet.set(f,feet)}feet.dust-=dt;if(feet.y<ground&&f.y===ground){for(let i=0;i<(strongEffects?8:2);i++)detailSpark(f.x,ground-2,'#b49b78',(detailRandom()-.5)*170,-20-detailRandom()*55,.3,'dust')}feet.y=f.y;
 if(f.y===ground&&Math.abs(f.vx)>120&&feet.dust<=0){feet.dust=.16;detailSpark(f.x-f.face*18,ground-2,'#ad9572',-f.face*35,-25,.28,'dust')}
 const m=f.attack?.move;if(strongEffects&&detailTrailClock>=.045&&m&&(m.dash||m.rotate||m.isSuper)&&f.attack.frame>=m.startup&&f.attack.frame<m.startup+m.active){detailGhosts.push({f:{...f,attack:{...f.attack}},life:.13,max:.13});if(detailGhosts.length>6)detailGhosts.shift()}
 }
 if(detailTrailClock>=.045)detailTrailClock=0;
}
const updateBeforeDetail=update;update=function(dt){const advance=['playing','roundover','finished'].includes(mode)&&!superCinema&&!document.hidden;updateBeforeDetail(dt);if(advance&&!superCinema)updateDetailEffects(dt)};
function detailLine(g,points,color,width=2){g.strokeStyle=color;g.lineWidth=width;g.beginPath();points.forEach(([x,y],i)=>i?g.lineTo(x,y):g.moveTo(x,y));g.stroke()}
function drawDetailBurst(g,b){const p=b.age/b.life,r=8+p*(b.superHit?110:b.heavy?76:42);g.save();g.translate(b.x,b.y);g.globalAlpha=(1-p)*(strongEffects?1:.65);
 if(b.blocked){g.strokeStyle=b.color;g.lineWidth=3;g.beginPath();for(let i=0;i<=6;i++){const a=i*Math.PI/3,x=Math.cos(a)*r*.65,y=Math.sin(a)*r;i?g.lineTo(x,y):g.moveTo(x,y)}g.stroke();detailLine(g,[[-8,-r*.6],[6,0],[-8,r*.6]],'#effcff',2)}
 else{g.strokeStyle=b.color;g.lineWidth=b.heavy?3:2;for(let i=0;i<(strongEffects?10:4);i++){const angle=i*Math.PI*2/(strongEffects?10:4)+b.seed,len=i%2?r:r*.6;detailLine(g,[[Math.cos(angle)*r*.18,Math.sin(angle)*r*.18],[Math.cos(angle)*len,Math.sin(angle)*len]],i%2?b.color:'#fff5d2',g.lineWidth)}
 g.globalAlpha*=(1-p);g.fillStyle='#fff4cf';g.beginPath();g.moveTo(-r*.22,0);g.lineTo(0,-r*.4);g.lineTo(r*.22,0);g.lineTo(0,r*.4);g.closePath();g.fill();
 if((b.id==='brick'||b.id==='rook')&&b.heavy){g.translate(0,ground-b.y-2);for(let i=0;i<4;i++){const sign=i<2?-1:1;detailLine(g,[[0,0],[sign*r*.35,(i%2?1:-1)*7],[sign*r*.6,0],[sign*r,(i%2?-1:1)*6]],'#d0b58c',2)}}
 }g.restore()}
function drawElementDetail(g,f){const a=f.attack,m=a?.move;if(!m||(!m.cooldown&&!m.isSuper)||m.counter||m.dodge)return;const phase=attackProgress(a);if(phase.phase==='recover')return;const pal=EFFECT_PALETTES[f.character],power=m.isSuper?1.35:1,t=detailClock*10,charge=phase.phase==='charge';g.save();g.translate(f.x,f.y-75);g.scale(f.face,1);g.globalAlpha=charge?.45:.8;g.lineWidth=2;const radius=(charge?16+phase.p*20:42+Math.sin(phase.p*Math.PI)*24)*power;
 if(f.character==='volt'){for(let j=0;j<(strongEffects?4:2);j++){const points=[];for(let i=0;i<7;i++)points.push([20+j*9+Math.sin(i*2.7+t+j)*9,-i*radius/3+35]);detailLine(g,points,pal[j%3],j===0?3:1)}}
 else if(f.character==='ember'){for(let j=0;j<(strongEffects?7:3);j++){const x=20+j*8,y=Math.sin(t+j)*9;g.fillStyle=pal[j%3];g.beginPath();g.moveTo(x-7,y+20);g.quadraticCurveTo(x-15,y-8,x+Math.sin(t+j)*8,y-radius);g.quadraticCurveTo(x+16,y-4,x+7,y+20);g.fill()}}
 else if(f.character==='cipher'){for(let ring=0;ring<2;ring++){g.strokeStyle=pal[ring];g.beginPath();g.arc(35,0,radius*(ring?.7:1),t*.1+ring,t*.1+ring+Math.PI*1.7);g.stroke()}for(let j=0;j<4;j++){const an=j*Math.PI/2+t*.2,x=35+Math.cos(an)*radius,y=Math.sin(an)*radius;detailLine(g,[[x-3,y],[x,y-5],[x+3,y],[x,y+5],[x-3,y]],pal[2],1)}}
 else if(f.character==='jade'||f.character==='goldie'){for(let j=0;j<(strongEffects?4:2);j++){g.strokeStyle=pal[j%3];g.lineWidth=j%2?1:3;g.beginPath();g.ellipse(10,35+j*5,radius+j*9,12+j*5,t*.12+j,0,Math.PI*1.55);g.stroke()}if(f.character==='goldie'&&strongEffects)for(let j=0;j<6;j++){const an=t*.2+j;g.fillStyle=pal[j%3];g.fillRect(Math.cos(an)*radius,30+Math.sin(an)*22,3,5)}}
 else if(f.character==='haze'){for(let j=0;j<(strongEffects?7:3);j++){const y=-40+j*14,x=Math.sin(t+j)*10;detailLine(g,[[-radius+x,y],[30+x,y-3],[radius*.8,y-9]],pal[j%3],j%2?1:3)}}
 else{g.translate(15,ground-f.y+73);for(let j=0;j<(strongEffects?3:1);j++){g.strokeStyle=pal[j%3];g.beginPath();g.ellipse(0,j*3,radius+j*18,9+j*5,0,0,Math.PI*1.8);g.stroke()}}
 g.restore();}
const drawBeforeDetail=draw;draw=function(){drawBeforeDetail();if(!['playing','paused','roundover','finished'].includes(mode))return;ctx.save();
 if(!superCinema){if(strongEffects){for(const ghost of detailGhosts){ctx.save();ctx.globalAlpha=.14*ghost.life/ghost.max;renderStreetFighter(ctx,ghost.f);ctx.restore()}}
 for(const p of projectiles){const pal=EFFECT_PALETTES[p.owner.character]||EFFECT_PALETTES.volt;ctx.save();ctx.globalCompositeOperation='lighter';for(let j=strongEffects?6:2;j>=1;j--){ctx.globalAlpha=(1-j/8)*.5;ctx.fillStyle=pal[j%3];ctx.beginPath();ctx.ellipse(p.x-p.dir*j*13,p.y+Math.sin(detailClock*16+j)*3,12-j,Math.max(2,10-j),0,0,Math.PI*2);ctx.fill()}ctx.globalAlpha=.85;ctx.strokeStyle=pal[0];ctx.lineWidth=2;ctx.beginPath();ctx.ellipse(p.x,p.y,25,18,detailClock*2,0,Math.PI*1.7);ctx.stroke();if(p.owner.character==='ember'){for(let flame=0;flame<(strongEffects?4:2);flame++){const y=p.y-12+flame*8;detailLine(ctx,[[p.x-p.dir*8,y],[p.x-p.dir*(30+Math.sin(detailClock*20+flame)*8),y-5],[p.x-p.dir*55,y+Math.sin(detailClock*16+flame)*6]],pal[flame%3],3-flame*.4)}}else if(p.owner.character==='cipher'){ctx.strokeStyle=pal[1];ctx.beginPath();ctx.ellipse(p.x,p.y,30,24,-detailClock*3,0,Math.PI*1.5);ctx.stroke();for(let j=0;j<3;j++){const a=detailClock*4+j*Math.PI*2/3,x=p.x+Math.cos(a)*32,y=p.y+Math.sin(a)*26;detailLine(ctx,[[x-3,y],[x,y-4],[x+3,y],[x,y+4],[x-3,y]],pal[2],1)}}ctx.restore()}
 for(const f of [player,enemy])drawElementDetail(ctx,f);for(const b of detailBursts)drawDetailBurst(ctx,b);
 for(const s of detailSparks){ctx.globalAlpha=Math.max(0,s.life/s.max)*(strongEffects?1:.65);ctx.fillStyle=s.color;if(s.kind==='dust'){const size=2+(1-s.life/s.max)*7;ctx.fillRect(s.x-size/2,s.y-size/2,size*1.7,size*.55)}else{ctx.lineWidth=s.kind==='guard'?2:1.5;ctx.strokeStyle=s.color;ctx.beginPath();ctx.moveTo(s.x,s.y);ctx.lineTo(s.x-s.vx*.022,s.y-s.vy*.022);ctx.stroke();ctx.fillRect(s.x-1,s.y-1,2,2)}}
 }else{const f=superCinema.fighter;ctx.strokeStyle=f.color;ctx.globalAlpha=.65;ctx.lineWidth=2;for(const y of [143,335])detailLine(ctx,[[40,y],[150,y-7],[950,y-7],[1060,y]],f.color,2);if(strongEffects)for(let j=0;j<8;j++){const y=157+j*23;detailLine(ctx,[[0,y],[55+(j%3)*20,y-8]],f.color,1);detailLine(ctx,[[1100,y],[1045-(j%3)*20,y-8]],f.color,1)}}ctx.restore();};
